// Marks the request as coming from the public webhook (no admin key was checked).
const request = $input.first().json;
return [{ json: { scope: 'public', body: request.body ?? {} } }];

// Marks the request as admin. The admin webhook uses Header Auth, so n8n has already rejected
// any request without the right X-Admin-Key before this node runs.
const request = $input.first().json;
return [{ json: { scope: 'admin', body: request.body ?? {} } }];

// Login check only. The admin webhook's Header Auth already rejected a wrong X-Admin-Key, so reaching
// this node means the key is right. No Data Table is read: signing in must not depend on the guest list.
return [{ json: { status: 200, body: { ok: true }, write: null } }];

// Every guest-side rule of the invitation API lives here: invitation lookup, RSVP, access card,
// admin guest list, and QR check-in. It returns { status, body, write }; `write` (if any) tells
// the next nodes which Data Table row to save.
const request = $('New token').first().json;
const { scope, body } = request;
const rawToken = request.token ?? request.data;
// A new token starts with a letter (a-f), so a spreadsheet can never read it as a number.
const newToken = typeof rawToken === 'string' && /^[0-9]/.test(rawToken) ? 'abcdef'[Number(rawToken[0]) % 6] + rawToken.slice(1) : rawToken;
const rows = $input.all().map((item) => item.json).filter((row) => row && row.id !== undefined && row.token);

const TOKEN = /^[a-f0-9]{8,64}$/; // new links use 16 hex characters; the older 8- and 64-character ones still work
const now = new Date().toISOString();
const reply = (status, payload, write = null) => [{ json: { status, body: payload, write } }];
const fail = (status, message) => reply(status, { error: message });
const hasRsvp = (row) => row.rsvp_status === 'yes' || row.rsvp_status === 'no';
const reservation = (row) => ({
  id: `R${row.id}`,
  token: row.token,
  name: row.name,
  attending: row.rsvp_status,
  event: row.rsvp_event || '',
  guests: Number(row.rsvp_guests) || 0,
  createdAt: row.rsvp_at,
  pax: Number(row.pax) > 0 ? Number(row.pax) : null, // seats the organiser assigned (empty = use the RSVP count)
  table: row.table_name || '',
});
const byToken = (value) => (typeof value === 'string' && TOKEN.test(value) ? rows.find((row) => row.token === value) : undefined);

const action = typeof body.action === 'string' ? body.action : '';
const ADMIN_ONLY = ['admin-check', 'admin-guests', 'admin-add-guest', 'admin-reservations', 'checkin'];
if (ADMIN_ONLY.includes(action) && scope !== 'admin') return fail(403, 'Admin access required.');

switch (action) {
  // ---- Public: the guest opens their personal link ----
  case 'invitation': {
    const guest = byToken(body.token);
    if (!guest) return fail(404, 'Invitation not found. Please use the personal link sent by the organizer.');
    return reply(200, {
      name: guest.name,
      maxGuests: Number(guest.max_guests) || 1,
      reservation: hasRsvp(guest) ? reservation(guest) : null,
    });
  }

  // ---- Public: the guest reopens their access card ----
  case 'reservation': {
    const guest = byToken(body.token);
    if (!guest || !hasRsvp(guest)) return fail(404, 'Reservation not found. Please use your access card link.');
    return reply(200, reservation(guest));
  }

  // ---- Public: the guest sends their RSVP (once per invitation) ----
  case 'rsvp': {
    const { attending, requestKey } = body;
    if (!['yes', 'no'].includes(attending) || typeof requestKey !== 'string' || !/^[\w-]{16,100}$/.test(requestKey)) {
      return fail(400, 'Please enter a valid name and attendance.');
    }
    const guest = byToken(body.invitationToken);
    if (!guest) return fail(403, 'Please use your personal invitation link to confirm your attendance.');
    // One RSVP per invitation: reopening or resubmitting returns the original.
    if (hasRsvp(guest)) return reply(200, reservation(guest));
    const event = attending === 'yes' ? body.event : '';
    if (attending === 'yes' && event !== 'reception') return fail(400, 'Choose an event.');
    // The party size is whatever the organiser set for this invitation (pax); the guest is not asked.
    const guests = attending === 'yes' ? Number(guest.max_guests) || 1 : 0;
    const columns = { rsvp_status: attending, rsvp_event: event, rsvp_guests: guests, rsvp_request_key: requestKey, rsvp_at: now };
    return reply(201, reservation({ ...guest, ...columns }), { op: 'rsvp', id: guest.id, columns });
  }

  // ---- Admin ----
  case 'admin-check':
    return reply(200, { ok: true });

  case 'admin-guests': {
    const list = [...rows]
      .sort((a, b) => String(b.createdAt).localeCompare(String(a.createdAt)) || Number(b.id) - Number(a.id))
      .slice(0, 100)
      .map((row) => ({
        id: String(row.id),
        token: row.token,
        name: row.name,
        maxGuests: Number(row.max_guests) || 1,
        createdAt: row.createdAt,
        reservationId: hasRsvp(row) ? `R${row.id}` : null,
        phone: row.phone || '',
        inviteSentAt: row.invite_sent_at || null,
        pax: Number(row.pax) > 0 ? Number(row.pax) : null,
        table: row.table_name || '',
      }));
    return reply(200, list);
  }

  case 'admin-add-guest': {
    const name = typeof body.name === 'string' ? body.name.trim() : '';
    const phone = typeof body.phone === 'string' ? body.phone.trim() : '';
    const maxGuests = body.maxGuests;
    const table = typeof body.table === 'string' ? body.table.trim() : '';
    const pax = body.pax === undefined || body.pax === null || body.pax === '' ? null : body.pax;
    if (!name || name.length > 120 || phone.length > 30 || !Number.isInteger(maxGuests) || maxGuests < 1 || maxGuests > 5) {
      return fail(400, 'Enter a guest name and a party limit between 1 and 5.');
    }
    if (table.length > 60 || (pax !== null && (!Number.isInteger(pax) || pax < 1 || pax > 20))) {
      return fail(400, 'Pax must be between 1 and 20, and the table name at most 60 characters.');
    }
    if (!TOKEN.test(newToken ?? '') || rows.some((row) => row.token === newToken)) return fail(500, 'Could not create a secure link. Please try again.');
    const columns = {
      name, phone, title: '', max_guests: maxGuests, pax: pax ?? 0, table_name: table, token: newToken, invite_sent_at: '',
      rsvp_status: '', rsvp_event: '', rsvp_guests: 0, rsvp_request_key: '', rsvp_at: '',
      reception_checkin_at: '',
    };
    return reply(201, { id: '', token: newToken, name, maxGuests, createdAt: now, reservationId: null, pax, table }, { op: 'add', columns });
  }

  case 'admin-reservations': {
    const search = typeof body.search === 'string' ? body.search.trim().toLowerCase() : '';
    const event = body.event ?? 'all';
    const attendance = body.attendance ?? 'all';
    const status = body.status ?? 'all';
    const date = body.date ?? '';
    const page = Number(body.page ?? 1);
    if (!Number.isInteger(page) || page < 1 || search.length > 120
      || !['all', 'reception'].includes(event)
      || !['all', 'yes', 'no'].includes(attendance)
      || !['all', 'checked-in', 'not-checked-in'].includes(status)
      || (date && !/^\d{4}-\d{2}-\d{2}$/.test(date))) {
      return fail(400, 'Invalid filters.');
    }
    const answered = rows.filter(hasRsvp);
    const matching = answered
      .filter((row) => {
        if (search && !String(row.name).toLowerCase().includes(search) && !`R${row.id}`.toLowerCase().includes(search)) return false;
        if (event !== 'all' && row.rsvp_event !== event && row.rsvp_event !== 'both') return false;
        if (attendance !== 'all' && row.rsvp_status !== attendance) return false;
        if (date && String(row.rsvp_at).slice(0, 10) !== date) return false;
        if (status !== 'all') {
          const seen = Boolean(row.reception_checkin_at);
          if ((status === 'checked-in') !== seen) return false;
        }
        return true;
      })
      .sort((a, b) => String(b.rsvp_at).localeCompare(String(a.rsvp_at)) || Number(b.id) - Number(a.id));
    const entries = matching.slice((page - 1) * 30, page * 30).map((row) => ({
      id: `R${row.id}`,
      name: row.name,
      attending: row.rsvp_status,
      event: row.rsvp_event || '',
      guests: Number(row.rsvp_guests) || 0,
      createdAt: row.rsvp_at,
      receptionScannedAt: row.reception_checkin_at || null,
      pax: Number(row.pax) > 0 ? Number(row.pax) : null,
      table: row.table_name || '',
    }));
    let checkedInCards = 0;
    let admittedGuests = 0;
    for (const row of answered) {
      if (row.reception_checkin_at) { checkedInCards += 1; admittedGuests += Number(row.rsvp_guests) || 0; }
    }
    const expectedGuests = answered.reduce((sum, row) => sum + (row.rsvp_status === 'yes' ? Number(row.rsvp_guests) || 0 : 0), 0);
    return reply(200, {
      entries,
      total: matching.length,
      page,
      pageSize: 30,
      summary: { reservations: answered.length, expectedGuests, checkedInCards, admittedGuests },
    });
  }

  // ---- Admin: the entrance scans a QR card ----
  case 'checkin': {
    const match = typeof body.qr === 'string' && /^ASW:v1:([a-f0-9]{8,64}):(reception)$/.exec(body.qr.trim());
    if (!match) return fail(400, 'Invalid QR code. Please use a newly issued entrance access card.');
    const event = match[2];
    if (body.event !== event) return fail(400, 'This card is for a different event. Select the correct entrance or ask for the other card.');
    const guest = byToken(match[1]);
    if (!guest || guest.rsvp_status !== 'yes' || (guest.rsvp_event !== 'both' && guest.rsvp_event !== event)) {
      return fail(403, 'This access card is not valid for admission.');
    }
    const field = `${event}_checkin_at`;
    const person = {
      id: `R${guest.id}`,
      name: guest.name,
      guests: Number(guest.rsvp_guests) || 0,
      pax: Number(guest.pax) > 0 ? Number(guest.pax) : null,
      table: guest.table_name || '',
    };
    if (guest[field]) return reply(200, { duplicate: true, reservation: person, event, scannedAt: guest[field] });
    const columns = { reception_checkin_at: now };
    return reply(200, { duplicate: false, reservation: person, event, scannedAt: now }, { op: 'checkin', id: guest.id, columns });
  }

  default:
    return fail(400, 'Unknown request.');
}

// After a Data Table write: send back the reply that "Handle guest action" prepared. A newly added
// guest only gets its row id and creation time once it has been saved.
const plan = $('Handle guest action').first().json;
const saved = $input.first().json;
const body = { ...plan.body };
if (plan.write && plan.write.op === 'add') {
  body.id = String(saved.id);
  body.createdAt = saved.createdAt ?? body.createdAt;
}
return [{ json: { status: plan.status, body } }];

// Wishes ("Kind Words"): list the latest 100 for the website, all of them (up to 500) for the admin desk, or add one. A repeated request key returns the
// wish that was already saved, so a double tap never posts twice.
const { body, scope } = $('New token').first().json;
const rows = $input.all().map((item) => item.json).filter((row) => row && row.id !== undefined && row.name);
const now = new Date().toISOString();
const reply = (status, payload, write = null) => [{ json: { status, body: payload, write } }];
const fail = (status, message) => reply(status, { error: message });
const wish = (row) => ({ id: String(row.id), name: row.name, message: row.message, createdAt: row.createdAt });

if (body.action === 'wishes-list') return reply(200, rows.slice(0, 100).map(wish));

if (body.action === 'admin-wishes') return scope === 'admin' ? reply(200, rows.map(wish)) : fail(403, 'Admin access required.');

if (body.action === 'wish-add') {
  const { name, message, requestKey } = body;
  if (typeof name !== 'string' || !name.trim() || name.length > 120
    || typeof message !== 'string' || !message.trim() || message.length > 2000
    || typeof requestKey !== 'string' || !/^[\w-]{16,100}$/.test(requestKey)) {
    return fail(400, 'Please enter a name and a wish of up to 2,000 characters.');
  }
  const previous = rows.find((row) => row.request_key === requestKey);
  if (previous) return reply(200, wish(previous));
  const columns = { request_key: requestKey, name: name.trim(), message: message.trim() };
  return reply(201, { id: '', name: columns.name, message: columns.message, createdAt: now }, { op: 'add', columns });
}

return fail(400, 'Unknown request.');

// After the wish is saved: reply with it, using the id and time the Data Table gave it.
const plan = $('Handle wish action').first().json;
const saved = $input.first().json;
const body = { ...plan.body, id: String(saved.id), createdAt: saved.createdAt ?? plan.body.createdAt };
return [{ json: { status: plan.status, body } }];
